class Solution:
    def restoreString(self, s: str, indices: List[int]) -> str:
        chars = list(s)
        idx = list(indices)
        for i in range(len(chars)):
            while idx[i] != i:
                j = idx[i]
                chars[i], chars[j] = chars[j], chars[i]
                idx[i], idx[j] = idx[j], idx[i]
        return ''.join(chars)

