var restoreString = function(s, indices) {
    const chars = s.split('');
    const idx = [...indices];
    for (let i = 0; i < chars.length; i++) {
        while (idx[i] !== i) {
            const j = idx[i];
            [chars[i], chars[j]] = [chars[j], chars[i]];
            [idx[i], idx[j]] = [idx[j], idx[i]];
        }
    }
    return chars.join('');
};
